"use client";
import { useId, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { folderFanLayout } from "./native-fan.js";
import { captureRects, animateLayout } from "./native-motion.js";
import { nativeMotionSpring } from "./native-spring.js";
import "./roc.css";
export interface TraySource { id:string;width:number;height:number;content:ReactNode }
/** Syuze's measured source fan and action springs with renderer-neutral children.
 * Same input/audio nodes stay mounted; no preview adapter is imposed on assets. */
export function SourceTray({items,label="Sources"}:{items:TraySource[];label?:string}){
 const [open,setOpen]=useState(false),root=useRef<HTMLDivElement>(null),layer=useRef<HTMLDivElement>(null),live=useRef(open),generation=useRef(0),id=useId();live.current=open;
 const nodes=()=>new Map([...layer.current!.querySelectorAll<HTMLElement>('[data-tray-id]')].map(n=>[n.dataset.trayId!,n]));
 const layout=()=>{
  const width=root.current!.clientWidth,height=300,frames=folderFanLayout({x:width/2-30,y:height-45,width:60},items),values=[...frames.values()];if(!values.length)return;
  const minX=Math.min(...values.map(p=>p.x)),maxX=Math.max(...values.map(p=>p.x+p.width)),minY=Math.min(...values.map(p=>p.y));
  const scale=Math.min(1,(width-24)/(maxX-minX),(height-70)/(height-45-minY));
  for(const [key,node]of nodes()){const p=frames.get(key)!;node.style.transform=`translate(${live.current?width/2+(p.x-width/2)*scale:width/2-p.width*.12}px,${live.current?height-45+(p.y-(height-45))*scale:height-70}px) scale(${live.current?scale:.24})`;}
 };
 const toggle=()=>{const before=captureRects(nodes());live.current=!live.current;setOpen(live.current);const token=++generation.current;layer.current!.hidden=false;layout();void animateLayout(nodes(),before,{spring:()=>nativeMotionSpring(live.current?'unfold':'refold',()=>.5)}).then(()=>{if(token===generation.current&&!live.current)layer.current?.querySelectorAll('audio').forEach(a=>a.pause());});};
 useLayoutEffect(()=>{layout();const observer=new ResizeObserver(()=>{const before=captureRects(nodes());layout();void animateLayout(nodes(),before,{spring:nativeMotionSpring('unfold',()=>.5)});});observer.observe(root.current!);return()=>{observer.disconnect();generation.current++;nodes().forEach(n=>n.getAnimations().forEach(a=>a.cancel()));};},[items.map(i=>`${i.id}:${i.width}:${i.height}`).join('|')]);
 return <div ref={root} className="roc-source-tray" onKeyDown={e=>{if(e.key==='Escape'&&open){e.stopPropagation();toggle();root.current?.querySelector<HTMLButtonElement>('.roc-tray-toggle')?.focus();}}}>
  <div ref={layer} id={id} className="roc-tray-layer" inert={!open} aria-hidden={!open}>{items.map(item=><article key={item.id} data-tray-id={item.id} className="roc-tray-item" style={{width:item.width,height:item.height}}>{item.content}</article>)}</div>
  <button className="roc-tray-toggle" type="button" aria-controls={id} aria-expanded={open} onClick={toggle}>{open?'Gather':label} · {items.length}</button>
 </div>;
}

// Extracted from Syuze; MIT Copyright (c) 2026 Songhai. See SOURCE-LICENSE.txt.
// Dense shelves fan upward from the folder; cards keep their actual dimensions.
export function folderFanLayout(folder,items){
 const layout=new Map(),gap=20,rows=[];
 const remaining=items.map((item,index)=>({item,index})).sort((a,b)=>b.item.width*b.item.height-a.item.width*a.item.height||a.index-b.index).map(v=>v.item);
 const columns=items.length<=5?items.length:Math.ceil(Math.sqrt(items.length*1.6));
 const baseWidth=remaining.slice(0,columns).reduce((sum,i)=>sum+i.width,0)+Math.max(0,columns-1)*gap;
 while(remaining.length){
  const budget=baseWidth*Math.pow(.82,rows.length),row=[];let width=0;
  while(remaining.length){const item=remaining[0],next=width+(row.length?gap:0)+item.width;if(row.length&&next>budget)break;row.push(remaining.shift());width=next;}
  rows.push({items:row,width,height:Math.max(...row.map(i=>i.height))});
 }
 let bottom=folder.y-24;
 for(const row of rows){
  const center=folder.x+folder.width/2,radius=(row.width-(row.items[0].width+row.items.at(-1).width)/2)/2,rise=row.items.length>1?Math.min(12,row.width*.012):0;
  let x=center-row.width/2;
  for(const item of row.items){const t=radius?Math.max(-1,Math.min(1,(x+item.width/2-center)/radius)):0,lift=rise*(1-t*t);layout.set(item.id,{x,y:bottom-item.height-lift,width:item.width,height:item.height,rotation:0});x+=item.width+gap;}
  bottom-=row.height+24+rise;
 }
 return layout;
}

// Extracted from Syuze; MIT Copyright (c) 2026 Songhai. See SOURCE-LICENSE.txt.
import {sampleSpring, springFrames, projectInertia} from './native-spring.js';
export {createVelocityTracker, projectInertia} from './native-spring.js';
const active = new WeakMap();
const reducedMotion = () => globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
const rectOf = node => { const {x,y,left,top,width,height,right,bottom}=node.getBoundingClientRect(); return {x,y,left,top,width,height,right,bottom}; };
const cancel = node => { node.getAnimations().forEach(a=>a.cancel()); active.delete(node); };
const vector = (transform, width, height) => {
  const m = new DOMMatrix(transform === 'none' ? undefined : transform);
  const sx = Math.hypot(m.a,m.b) || 1;
  return {x:m.e,y:m.f,angle:Math.atan2(m.b,m.a),sx,sy:(m.a*m.d-m.b*m.c)/sx,width:parseFloat(width)||0,height:parseFloat(height)||0};
};
const transform = v => `translate(${v.x}px,${v.y}px) rotate(${v.angle}rad) scale(${v.sx},${v.sy})`;
const css = v => ({transform:transform(v),width:`${Math.max(.01,v.width)}px`,height:`${Math.max(.01,v.height)}px`});

/** Current physical velocity, in world units/second. External cancellation resets it. */
export function sampleMotion(node) {
  const record = active.get(node);
  if (!record || record.animation.playState !== 'running') return {velocity:{},values:null};
  const time = Math.max(0, Number(record.animation.currentTime || 0) / 1000);
  const values={}, velocity={};
  for (const key of Object.keys(record.to)) {
    const sample = sampleSpring(record.from[key],record.to[key],record.velocity[key]||0,time,record.options);
    values[key]=sample.position; velocity[key]=sample.velocity;
  }
  return {values,velocity};
}
function run(node, from, to, velocity, options, camera = false) {
  // Use the nearest equivalent angle; crossing ±π must not turn a card around.
  while (to.angle-from.angle>Math.PI) from.angle+=Math.PI*2;
  while (to.angle-from.angle< -Math.PI) from.angle-=Math.PI*2;
  const samples=springFrames(from,to,velocity,options), duration=samples.at(-1).time*1000;
  const frames=samples.map(s=>({...(camera ? {transform:transform(s.values)} : css(s.values)),offset:duration?s.time*1000/duration:1}));
  const animation=node.animate(frames,{duration,easing:'linear'});
  const record={animation,from,to,velocity,options}; active.set(node,record);
  return animation.finished.catch(()=>{}).finally(()=>{if(active.get(node)===record)active.delete(node);});
}
/** Snapshot painted geometry and physical speed before changing destination styles. */
export function captureRects(nodes) {
  return new Map([...nodes].map(([id,node])=>{
    const style=getComputedStyle(node);
    return [id,{node,parent:node.parentElement,rect:rectOf(node),transform:style.transform,width:style.width,height:style.height,velocity:sampleMotion(node).velocity}];
  }));
}
/** Final inline geometry must be applied first. duration:0 disables motion; positive duration
 * is retained for API compatibility. Physical stiffness/damping determine actual settling. */
export function animateLayout(nodes,before,{duration=420,origins=new Map(),spring={},preserveVelocity=true,progressVelocity}={}) {
  for(const node of nodes.values())cancel(node);
  if(reducedMotion()||duration<=0)return Promise.resolve();
  const moves=[];
  for(const [id,node] of nodes){
    const old=before.get(id),origin=origins.get(id); if(!old&&!origin)continue;
    const style=getComputedStyle(node),to=vector(style.transform,style.width,style.height);
    let from,velocity={};
    if(old?.node===node&&old.parent===node.parentElement){from=vector(old.transform,old.width,old.height);velocity=preserveVelocity?(old.velocity||{}):{};}
    else {
      const source=origin?.rect||origin||old.rect,target=rectOf(node);
      if(!source.width||!source.height||!target.width||!target.height)continue;
      const parent=node.parentElement,parentTransform=parent?getComputedStyle(parent).transform:'none';
      const m=new DOMMatrix(parentTransform==='none'?undefined:parentTransform),scale=Math.hypot(m.a,m.b)||1;
      from={...to,x:to.x+((source.left??source.x)+source.width/2-target.left-target.width/2)/scale,y:to.y+((source.top??source.y)+source.height/2-target.top-target.height/2)/scale,sx:to.sx*source.width/target.width,sy:to.sy*source.height/target.height};
    }
    if(progressVelocity!==undefined)velocity=Object.fromEntries(Object.keys(to).map(key=>[key,(to[key]-from[key])*progressVelocity]));
    if(Object.keys(to).some(k=>Math.abs(from[k]-to[k])>.00001||Math.abs(velocity[k]||0)>.001))moves.push({node,from,to,velocity,spring:typeof spring==='function'?spring(id,node):spring});
  }
  return Promise.all(moves.map(m=>run(m.node,m.from,m.to,m.velocity,m.spring)));
}
export function animateCamera(world,from,to,{duration=420,spring={}}={}) {
  const velocity=sampleMotion(world).velocity;
  const start=world.getAnimations().length?getComputedStyle(world).transform:from;
  cancel(world);world.style.transform=to;
  if(reducedMotion()||duration<=0||start===to)return Promise.resolve();
  return run(world,vector(start,0,0),vector(to,0,0),velocity,spring,true);
}
/** Release a dragged node, committing its bounded target immediately. Caller must persist
 * returned displacement in its model (projectInertia uses exactly the same calculation).
 * Spring damping follows a critically damped release so it settles without bouncing back. */
export function animateInertia(node,{velocity,decay=7,maxDistance=220,onFinish}={}) {
  const style=getComputedStyle(node),from=vector(style.transform,style.width,style.height);
  const displacement=projectInertia(velocity,{decay,maxDistance}),to={...from,x:from.x+displacement.x,y:from.y+displacement.y};
  cancel(node);node.style.transform=transform(to);
  const result=reducedMotion()?Promise.resolve():run(node,from,to,{x:displacement.x*decay,y:displacement.y*decay},{stiffness:decay*decay,damping:2*decay,mass:1});
  return result.then(()=>onFinish?.(displacement));
}

/** Native folder-lid constants recovered from compiled Spatial: stiffness100, damping10,
 * mass0.64, +20° around X, perspective2000. Caller owns bottom-edge transform-origin.
 * New runs start with zero velocity. Interrupted reversals optionally retain velocity
 * for browser continuity; that policy is not asserted to be native initialVelocity.
 * This dedicated 3D path never passes its matrix through the 2D layout decomposition.
 */
export function animateFolderLid(node,opening,{duration=420,preserveVelocity=true,spring={},perspective=2000,angle=20}={}) {
  const sampled=sampleMotion(node),style=getComputedStyle(node);
  const matrix=new DOMMatrix(style.transform==='none'?undefined:style.transform);
  const sideways=node.dataset.hinge==='side';
  const from={angle:(sideways?Math.atan2(matrix.m13,matrix.m11):Math.atan2(matrix.m23,matrix.m22))*180/Math.PI},to={angle:opening?angle:0};
  const velocity={angle:preserveVelocity?(sampled.velocity.angle||0):0};
  const options={stiffness:100,damping:10,mass:.64,...spring};
  const frame=v=>({transform:`perspective(${perspective}px) ${sideways?'rotateY':'rotateX'}(${sideways?-v.angle:v.angle}deg)`});
  cancel(node);node.style.transform=frame(to).transform;
  if(reducedMotion()||duration<=0||Math.abs(from.angle-to.angle)<.00001&&Math.abs(velocity.angle)<.00001)return Promise.resolve();
  const samples=springFrames(from,to,velocity,options),settling=samples.at(-1).time*1000;
  const animation=node.animate(samples.map(s=>({...frame(s.values),offset:s.time*1000/settling})),{duration:settling,easing:'linear'});
  const record={animation,from,to,velocity,options};active.set(node,record);
  return animation.finished.catch(()=>{}).finally(()=>{if(active.get(node)===record)active.delete(node);});
}

// Extracted from Syuze; MIT Copyright (c) 2026 Songhai. See SOURCE-LICENSE.txt.
/** Physical motion primitives. General default remains reconstructed; recovered native profiles are below. */
export const DEFAULT_SPRING = Object.freeze({stiffness: 400, damping: 38, mass: 1});

/** Analytic damped oscillator. Position and velocity are in units and units/second. */
export function sampleSpring(from, to, velocity, seconds, options = {}) {
  const {stiffness:k, damping:c, mass:m} = {...DEFAULT_SPRING, ...options};
  if (!(k > 0 && m > 0 && c >= 0)) throw new RangeError('Invalid spring parameters');
  const t = Math.max(0, seconds), a = c / (2 * m), w2 = k / m, d = from - to;
  let x, v;
  if (Math.abs(a * a - w2) < 1e-7) {
    const b = velocity + a * d, e = Math.exp(-a * t);
    x = (d + b * t) * e; v = (b - a * (d + b * t)) * e;
  } else if (a * a < w2) {
    const w = Math.sqrt(w2 - a * a), b = (velocity + a * d) / w;
    const e = Math.exp(-a * t), cos = Math.cos(w * t), sin = Math.sin(w * t);
    x = e * (d * cos + b * sin);
    v = e * ((b * w - a * d) * cos - (d * w + a * b) * sin);
  } else {
    const q = Math.sqrt(a * a - w2), r1 = -a + q, r2 = -a - q;
    const b1 = (velocity - r2 * d) / (r1 - r2), b2 = d - b1;
    x = b1 * Math.exp(r1 * t) + b2 * Math.exp(r2 * t);
    v = r1 * b1 * Math.exp(r1 * t) + r2 * b2 * Math.exp(r2 * t);
  }
  return {position: to + x, velocity: v};
}

/** Vector spring samples; settle by position AND speed, then commit an exact destination. */
export function springFrames(from, to, velocity = {}, options = {}) {
  const fps = options.fps || 120, frames = [], keys = Object.keys(to);
  let quiet = 0;
  // WAAPI interpolates linearly between samples. A coarse initial segment would
  // visibly discard incoming speed during a high-acceleration reversal.
  const times = [...new Set([0, .001, .002, .004, ...Array.from({length:fps*4},(_,i)=>(i+1)/fps)])].sort((a,b)=>a-b);
  for (const time of times) {
    const values = {}, speeds = {};
    let resting = true;
    for (const key of keys) {
      const s = sampleSpring(from[key], to[key], velocity[key] || 0, time, options);
      values[key] = s.position; speeds[key] = s.velocity;
      const tolerance = key.startsWith('s') ? .0001 : key === 'angle' ? .0001 : .03;
      resting &&= Math.abs(s.position - to[key]) < tolerance && Math.abs(s.velocity) < tolerance * 10;
    }
    frames.push({time, values, velocity:speeds});
    quiet = resting ? quiet + 1 : 0;
    if (quiet >= 3) break;
  }
  const last = frames.at(-1);
  last.values = {...to}; last.velocity = Object.fromEntries(keys.map(key => [key, 0]));
  return frames;
}

/** Exponential release: distance is v/decay, bounded as a vector, not per axis. */
export function projectInertia(velocity, {decay = 7, maxDistance = 220} = {}) {
  if (!(decay > 0 && maxDistance >= 0)) throw new RangeError('Invalid inertia parameters');
  const distance = Math.hypot(velocity.x, velocity.y) / decay;
  const factor = distance > maxDistance ? maxDistance / distance : 1;
  return {x: velocity.x / decay * factor, y: velocity.y / decay * factor};
}

/** Recent pointer history. An idle pause before release deliberately removes momentum. */
export function createVelocityTracker({windowMs = 85, staleMs = 100} = {}) {
  let points = [];
  return {
    add(x, y, time) { points.push({x,y,time}); points = points.filter(p => time - p.time <= windowMs); },
    sample(time) {
      const last = points.at(-1), first = points[0];
      if (!last || points.length < 2 || time - last.time >= staleMs || last.time === first.time) return {x:0,y:0};
      const seconds = (last.time - first.time) / 1000, fade = Math.max(0, 1 - (time - last.time) / staleMs);
      return {x:(last.x-first.x)/seconds*fade, y:(last.y-first.y)/seconds*fade};
    },
    reset() { points = []; }
  };
}

// Recovered ARM64 call sites and constants: research/native-folder-logic.md and
// native-pull-logic.md. CA's allowsOverdamping=false clamps to critical damping.
export function nativeMotionSpring(kind, random = Math.random) {
  if(kind==='dropGather'||kind==='dropSink'){const mass=(kind==='dropGather'?.24+.08*random():.16+.16*random())*.48;return {stiffness:100,damping:2*Math.sqrt(100*mass),mass};}
  if(kind==='unfold')return {stiffness:240,damping:20,mass:.8+.16*random()};
  if(kind==='refold'){const mass=.12+.12*random();return {stiffness:100,damping:2*Math.sqrt(100*mass),mass};}
  if(kind==='pullReturn')return {stiffness:400,damping:24,mass:(.8+.4*random())*.64};
  if(kind==='lidOpen')return {stiffness:100,damping:10,mass:.64};
  if(kind==='lidClose')return {stiffness:100,damping:2*Math.sqrt(100*.32),mass:.32};
  throw new RangeError('Unknown native motion kind');
}
export const nativePullShouldDetach = (elapsedMs, dx, dy, magnification) => elapsedMs>800 || Math.hypot(dx,dy)>500/magnification;

export interface Spring { stiffness?: number; damping?: number; mass?: number; fps?: number }
export function sampleSpring(from:number,to:number,velocity:number,seconds:number,options?:Spring):{position:number;velocity:number};
export function springFrames(from:Record<string,number>,to:Record<string,number>,velocity?:Record<string,number>,options?:Spring):{time:number;values:Record<string,number>;velocity:Record<string,number>}[];
export function nativeMotionSpring(kind:string,random?:()=>number):Spring;

